<script setup lang="ts">
import { computed, defineAsyncComponent, onBeforeUnmount, onMounted, ref } from 'vue';
import { layout, assignment } from '../contracts';
import type { AssetId, SceneStatus, ViewId } from '../scene/largeWarehouse';
const calibrationV2 = new URLSearchParams(location.search).get('calibration')==='v2';
const calibration = new URLSearchParams(location.search).has('calibration')&&!calibrationV2;
const Calibration = defineAsyncComponent(() => import('./App.vue'));
const CalibrationV2 = defineAsyncComponent(() => import('./CalibrationV2.vue'));
const host=ref<HTMLDivElement>();
const phase=ref('loading'); const error=ref(''); const mode=ref<ViewId>('overview');
const quality=ref('high');
const gallery=ref(false); const status=ref<SceneStatus>();
const catalog=ref<{id:AssetId;label:string;note:string;reference:string}[]>([]);
const runInput=ref<HTMLInputElement>();const integrationError=ref('');
let viewer: Awaited<ReturnType<typeof import('../scene/largeWarehouse')['mountWarehouse']>> | undefined;
let active=true;
const current=computed(()=>catalog.value.find(a=>a.id===mode.value));
const replay=computed(()=>status.value?.replay);
const timeLabel=(seconds=0)=>`${Math.floor(seconds/60).toString().padStart(2,'0')}:${Math.floor(seconds%60).toString().padStart(2,'0')}`;
const stageLabels:Record<string,string>={order_arrived:'Заказ принят',order_assigned:'Комплектация',sku_picked:'Товар отобран',tote_inducted:'На линии',pack_started:'Упаковка',order_packed:'Упакован',parcel_outfed:'К отгрузке',shipping_arrived:'Прибыл к отгрузке',parcel_scanned:'На паллете',pallet_sealed:'Паллета закрыта',order_dispatched:'Отгружен'};
const stage=computed(()=>Object.values(status.value?.orderStages||{})[0]||'order_arrived');
const selectedSlot=computed(()=>layout.slots.find(slot=>slot.slot_id===status.value?.selected));
const selectedLot=computed(()=>assignment.initial_lots.find(lot=>lot.slot_id===status.value?.selected));
function togglePlay(){if(replay.value?.playing)viewer?.replay.pause();else viewer?.replay.play();}
function seek(event:Event){viewer?.replay.seek(Number((event.target as HTMLInputElement).value));}
function changeSpeed(event:Event){viewer?.replay.setSpeed(Number((event.target as HTMLSelectElement).value));}
function followOrder(){viewer?.followOrder();}
async function toggleSound(){if(!viewer)return;if(!status.value?.audio.muted)viewer.audio.setMuted(true);else if(await viewer.audio.unlock())viewer.audio.setMuted(false);}
async function importRun(event:Event){
  const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;
  try{viewer?.loadRun(JSON.parse(await file.text()));integrationError.value='';}
  catch(reason){integrationError.value=reason instanceof Error?reason.message:String(reason);}
  (event.target as HTMLInputElement).value='';
}
const base=import.meta.env.BASE_URL;
function qualityChange(){viewer?.setQuality(quality.value);}
function choose(next:ViewId){mode.value=next;viewer?.setMode(next);gallery.value=false;}
onMounted(async()=>{
  if(calibration||calibrationV2)return;
  try{
    const module=await import('../scene/largeWarehouse');
    if(!active)return;
    catalog.value=[...module.assetCatalog];
    viewer=await module.mountWarehouse(host.value!,value=>{status.value=value;});
    if(!active){viewer.dispose();return;}
    phase.value='ready';
    Object.assign(window,{__QOIMA_VIEWER__:viewer});
  }catch(reason){error.value=reason instanceof Error?reason.message:String(reason);phase.value='error';}
});
onBeforeUnmount(()=>{active=false;viewer?.dispose();});
</script>

<template>
  <CalibrationV2 v-if="calibrationV2" />
  <Calibration v-else-if="calibration" />
  <main v-else class="studio" :data-phase="phase">
    <header class="masthead">
      <a class="wordmark" href="./" aria-label="QoimaTwin, общий вид"><span class="brand-icon">Q</span>Qoima<span>Twin</span></a>
      <div class="project-meta"><b></b>{{replay?.source==='run-v2'?'RUN V2':'VISUAL DEMO'}}<i>/</i>72 × 48 м<i>/</i>v2</div>
      <div class="header-actions"><input ref="runInput" type="file" accept="application/json,.json" hidden @change="importRun" /><button class="text-button import-run" @click="runInput?.click()">Открыть Run v2</button><button class="text-button" @click="gallery=!gallery" :aria-expanded="gallery">{{gallery?'Вернуться к модели':'Референсы'}} <span>↗</span></button></div>
    </header>
    <section class="viewport" aria-label="Интерактивная 3D-модель склада">
      <div ref="host" class="scene-host"></div>
      <div class="scene-heading"><div class="eyebrow">QOIMA / БОЛЬШОЙ СКЛАД</div><h1>{{current?.label||'Склад завтрашних заказов'}}</h1><p>{{current?.note||'12 проходов · 864 адреса · 24 сотрудника · 6 постов упаковки'}}</p></div>
      <div v-if="phase!=='ready'" class="loading" role="status">{{error||'Собираем пространство…'}}</div>
      <div v-if="integrationError||status?.warnings.length" class="integration-message" role="alert">{{integrationError||status?.warnings[0]}}<button @click="integrationError='';viewer?.loadVisualDemo()">Визуальное демо</button></div>
      <nav class="camera-tools" aria-label="Камера"><button @click="choose('overview')" :disabled="phase!=='ready'">Обзор <span>↖</span></button><button @click="viewer?.top()" :disabled="phase!=='ready'">Сверху <span>⊞</span></button><button @click="viewer?.focusSlot('S_A01_B01_L_01')" :disabled="phase!=='ready'||mode!=='overview'">Детали <span>⌕</span></button></nav>
      <nav v-if="mode==='overview'" class="zone-tools" aria-label="Зоны склада"><button @click="viewer?.flow()">Поток / упаковка</button><button @click="viewer?.docks('receiving')">Приёмка</button><button @click="viewer?.docks('shipping')">Отгрузка</button><button @click="viewer?.selectActor('P01')">Следовать P01</button></nav>
      <nav v-else class="zone-tools" aria-label="Ракурсы модели"><button v-for="(label,view) in {front:'Спереди',side:'Сбоку',rear:'Сзади',quarter:'Объём'}" :key="view" @click="viewer?.inspect(view)">{{label}}</button></nav>
      <aside v-if="mode==='overview'&&phase==='ready'" class="mini-map" aria-label="Миникарта склада"><svg viewBox="-1 -1 74 50" role="img" aria-label="План 72 на 48 метров"><defs><clipPath id="map-floor"><rect x="0" y="0" width="72" height="48"/></clipPath></defs><rect x="0" y="0" width="72" height="48" fill="#e9eadf" stroke="#788b7b" stroke-width=".4"/><rect v-for="rack in layout.racks" :key="rack.rack_id" :x="rack.root[0]-.45" :y="48-rack.root[2]-.75" width=".9" height="1.5" fill="#758c88"/><path v-for="segment in layout.conveyor.segments" :key="segment.segment_id" :d="`M${segment.from[0]} ${48-segment.from[2]} L${segment.to[0]} ${48-segment.to[2]}`" fill="none" stroke="#388c81" stroke-width=".55"/><polygon v-if="status?.viewportFootprint.length" :points="status.viewportFootprint.map(point=>`${point[0]},${48-point[2]}`).join(' ')" clip-path="url(#map-floor)" fill="#80a28e" fill-opacity=".12" stroke="#638d74" stroke-width=".3"/><circle v-for="(position,id) in status?.actorPositions" :key="id" :cx="position[0]" :cy="48-position[2]" r=".45" :fill="id===status?.selected?'#c48624':'#b88a46'"/><circle v-if="status" :cx="Math.max(0,Math.min(72,status.target[0]))" :cy="48-Math.max(0,Math.min(48,status.target[2]))" r="2" fill="none" stroke="#c48624" stroke-width=".5"/></svg><span>864 адреса <i>·</i> {{status?.triangles.toLocaleString('ru-RU')}} △</span></aside>
      <div v-if="status?.selected" class="selection-tag">{{status.selected}}<small>{{selectedSlot?(selectedSlot.level===1?'Нижний адрес отбора':'Верхний резерв'):status.activeLabels.find(label=>label.actorId===status?.selected)?.text||'Выбранный объект'}}</small><template v-if="selectedSlot"><template v-if="replay?.source==='visual-fixture'"><small>{{selectedLot?.sku_id||'Свободный адрес'}}<span v-if="selectedLot"> · {{selectedLot.quantity.toLocaleString('ru-RU')}} ед. на старте</span></small><small>{{selectedLot?.lot_id||'Партии нет'}} · уровень {{selectedSlot.level}}</small></template><small v-else>Адрес layout v2 · остатки Run не показаны</small></template></div>
      <div class="interaction-hint">↔ &nbsp; Вращайте сцену <i>·</i> Колесо — приближение <i>·</i> Нажмите на стеллаж</div>
      <span class="scene-caption">{{mode==='overview'?'Визуальная фикстура · данные синтетические':'Осмотр отдельной модели · масштаб в метрах'}}</span>
    </section>
    <section v-if="phase==='ready'" class="replay-bar" aria-label="Воспроизведение">
      <button class="play-button" @click="togglePlay" :disabled="mode!=='overview'" :aria-label="replay?.playing?'Пауза':'Воспроизвести'">{{replay?.playing?'Ⅱ':'▶'}}</button>
      <button class="reset-button" @click="viewer?.replay.reset()" aria-label="Сбросить время">↺</button>
      <div class="timeline"><div class="timeline-label"><strong>{{timeLabel(replay?.time)}} <span>/ {{timeLabel(replay?.duration)}}</span></strong><span class="order-stage">{{stageLabels[stage]||stage}}</span><span :class="{blocked:status?.blocked}">{{status?.blocked?'Линия удерживает груз':'VISUAL DEMO / synthetic'}}</span></div><input aria-label="Время воспроизведения" type="range" min="0" :max="replay?.duration||500" step=".1" :value="replay?.time||0" @input="seek" /></div>
      <select aria-label="Скорость воспроизведения" :value="replay?.speed||1" @change="changeSpeed"><option :value="1">1×</option><option :value="10">10×</option><option :value="30">30×</option><option :value="60">60×</option></select>
      <button class="follow-order" @click="followOrder" :disabled="mode!=='overview'">Следовать заказу ↗</button>
      <button class="sound-button" @click="toggleSound" :aria-label="status?.audio.muted?'Включить звук':'Выключить звук'">{{status?.audio.muted?'Звук выкл.':'Звук вкл.'}}</button><input class="volume" aria-label="Громкость" type="range" min="0" max="1" step=".01" :value="status?.audio.volume??.18" @input="viewer?.audio.setVolume(Number(($event.target as HTMLInputElement).value))" /><details class="audio-options"><summary aria-label="Категории звука">···</summary><div><label v-for="(label,key) in {ambience:'Фон',mechanical:'Механика',feedback:'Сигналы'}" :key="key"><input type="checkbox" :checked="status?.audio.categories[key]" @change="viewer?.audio.setCategory(key,($event.target as HTMLInputElement).checked)" />{{label}}</label></div></details>
    </section>
    <div class="scene-controls"><span class="source-caption">{{status?.sourceLabel||'Синтетическая визуальная фикстура'}} · backend отдельно</span><label><input type="checkbox" :checked="status?.reducedMotion" @change="viewer?.setReducedMotion(($event.target as HTMLInputElement).checked)" /> Спокойный режим</label><label>Качество <select v-model="quality" @change="qualityChange"><option value="low">Low</option><option value="high">Детально</option></select></label><span>{{status?.calls||0}} draw calls</span></div>
    <footer class="asset-dock">
      <button class="overview-tile" :class="{active:mode==='overview'}" @click="choose('overview')"><b>▦</b><span>Весь склад<small>Общий обзор</small></span></button><div class="dock-divider"></div>
      <div class="asset-list" aria-label="Модели"><button v-for="(asset,index) in catalog" :key="asset.id" :data-asset="asset.id" :class="{active:mode===asset.id}" @click="choose(asset.id)"><small>{{String(index+1).padStart(2,'0')}}</small><span>{{asset.label}}</span></button></div>
    </footer>
    <aside v-if="gallery" class="reference-gallery" aria-label="Сгенерированные референсы">
      <div class="gallery-title"><div><div class="eyebrow">ART DIRECTION</div><h2>От референса к объёму</h2><p>Референсы семейств и отдельные стенды. Формы сверены с геометрией v2.</p></div><button @click="gallery=false" aria-label="Закрыть референсы">×</button></div>
      <div class="gallery-grid"><figure v-for="asset in catalog" :key="asset.id"><a :href="`${base}references/${asset.reference}`" target="_blank" rel="noreferrer"><img :src="`${base}references/${asset.reference}`" :alt="`Референс: ${asset.label}, несколько ракурсов`" loading="lazy" /></a><figcaption><strong>{{asset.label}}</strong><span>{{asset.note}}</span><button @click="choose(asset.id)">Открыть 3D ↗</button></figcaption></figure></div>
    </aside>
  </main>
</template>

<style>
:root{font-family:'Segoe UI',Arial,sans-serif;color:#283b3b;background:#e9e7e0;font-synthesis:none}*{box-sizing:border-box}body{margin:0}button{font:inherit;color:inherit;cursor:pointer}button:disabled{opacity:.4;cursor:default}button:focus-visible,a:focus-visible{outline:2px solid #b47522;outline-offset:4px}
.studio{width:100%;height:100dvh;min-height:580px;display:flex;flex-direction:column;overflow:hidden}.masthead{height:78px;flex-shrink:0;margin:0 32px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #bac2bb70;position:relative;z-index:2}.wordmark{display:flex;align-items:center;gap:3px;font-size:22px;font-weight:650;color:#273f3e;text-decoration:none;letter-spacing:-.7px}.wordmark>span:last-child{font-weight:350}.brand-icon{display:grid;place-items:center;width:33px;height:33px;background:#2c4b46;color:#f7f0dc;border-radius:9px;font-size:22px;margin-right:10px;font-family:Georgia,serif;font-weight:400}.project-meta{display:flex;align-items:center;gap:10px;color:#6b7970;font-size:12px}.project-meta b{width:6px;height:6px;border-radius:50%;background:#6a8b70}.project-meta i{font-style:normal;opacity:.35;margin:0 7px}.text-button{border:0;background:transparent;font-size:12px}.text-button span{margin-left:16px}
.viewport{position:relative;flex:1;min-height:300px}.scene-host{position:absolute;inset:0;touch-action:none}.scene-host canvas{display:block;width:100%;height:100%}.scene-heading{position:absolute;top:28px;left:34px;pointer-events:none;max-width:430px}.viewport:has(.selection-tag) .scene-heading{visibility:hidden}.eyebrow{font-size:9px;letter-spacing:2.3px;color:#8b9586;font-weight:600}.scene-heading h1{font-size:clamp(24px,2.5vw,36px);margin:11px 0 8px;font-weight:420;letter-spacing:-1px}.scene-heading p{margin:0;font-size:11px;color:#788476;max-width:390px;line-height:1.6}.camera-tools{position:absolute;right:32px;top:32px;display:flex;gap:5px}.camera-tools button{border:1px solid #cbd0c4;border-radius:7px;background:#f5f3ebd9;padding:11px 13px;font-size:11px}.camera-tools button span{margin-left:18px;color:#87947f}.camera-tools button:hover:not(:disabled){background:#fffdf4}.interaction-hint{position:absolute;left:34px;bottom:16px;color:#899183;font-size:10px;pointer-events:none}.interaction-hint i{font-style:normal;margin:0 9px;color:#a1a895}.scene-caption{position:absolute;right:34px;bottom:20px;font-size:9px;color:#909788;pointer-events:none}.selection-tag{position:absolute;right:32px;top:90px;background:#fcf8eced;border-left:3px solid #d4a345;padding:14px 20px;font-size:13px;box-shadow:0 5px 30px #3b463718}.selection-tag small{display:block;font-size:10px;color:#88927d;margin-top:5px}.loading{position:absolute;inset:0;display:grid;place-items:center;background:#e9e7e0e8;font-size:15px}[data-phase=error] .loading{color:#9a463a;padding:30px}
.asset-dock{margin:0 28px 22px;height:88px;flex-shrink:0;display:flex;gap:18px;align-items:center;border:1px solid #d1d3c5;padding:10px 12px;background:#f5f3eccc;border-radius:12px}.overview-tile{min-width:146px;display:flex;align-items:center;gap:12px;border:0;background:transparent;padding:12px;text-align:left;font-size:12px;border-radius:8px}.overview-tile>b{font-size:30px;color:#8a9c89;font-weight:400}.overview-tile small{display:block;margin-top:4px;color:#899784;font-size:9px}.dock-divider{height:42px;width:1px;background:#d2d6c8;flex-shrink:0}.asset-list{display:flex;justify-content:space-around;flex:1;gap:5px;overflow-x:auto}.asset-list button{display:flex;flex-direction:column;gap:10px;align-items:flex-start;padding:12px 16px;border:0;background:transparent;text-align:left;white-space:nowrap;border-radius:7px;font-size:10px}.asset-list small{color:#95a18e;font-size:9px;font-variant-numeric:tabular-nums}.asset-list button.active,.overview-tile.active{background:#e3e8da;color:#345443}.asset-list button:hover{background:#e9ecdf}
.reference-gallery{position:absolute;inset:78px 0 0;z-index:5;overflow:auto;background:#eeede5;padding:30px}.gallery-title{display:flex;justify-content:space-between;max-width:1400px;margin:auto auto 28px}.gallery-title h2{font-size:30px;font-weight:400;margin:8px 0}.gallery-title p{font-size:12px;color:#809078}.gallery-title>button{border:0;background:transparent;font-size:30px;align-self:flex-start}.gallery-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px;max-width:1400px;margin:auto}.gallery-grid figure{margin:0;background:#faf8f1;border:1px solid #d5d8ca}.gallery-grid img{display:block;width:100%;aspect-ratio:1.2;object-fit:contain;background:#bababa}.gallery-grid figcaption{padding:16px;display:flex;flex-wrap:wrap;gap:8px 20px;align-items:center}.gallery-grid strong{font-size:13px;font-weight:500}.gallery-grid figcaption span{font-size:11px;color:#859177;flex:1}.gallery-grid figcaption button{border:0;background:transparent;font-size:11px}
@media(max-width:900px){.project-meta{display:none}.scene-caption{display:none}.asset-dock{margin:0 12px 12px;gap:8px}.asset-list button{padding:10px}.overview-tile{min-width:118px;padding:6px}.masthead{margin:0 20px;height:66px}.scene-heading{left:20px;top:20px}.scene-heading p{max-width:230px}.camera-tools{right:16px;top:110px}.interaction-hint{left:20px;font-size:9px}.reference-gallery{inset:66px 0 0}}@media(max-width:600px){.studio{min-height:620px}.gallery-grid{grid-template-columns:1fr}.reference-gallery{padding:20px}.scene-heading h1{font-size:28px}.scene-heading p{display:none}.camera-tools{left:20px;right:auto;top:100px}.overview-tile{min-width:100px}.overview-tile>b{display:none}.interaction-hint{font-size:8px}.interaction-hint i{margin:0 4px}}
</style>

<style>
.zone-tools{position:absolute;right:32px;top:86px;display:flex;gap:5px;max-width:490px;flex-wrap:wrap;justify-content:flex-end}.zone-tools button{border:0;border-bottom:1px solid #aebca955;background:#f0f0e4d9;padding:9px 11px;font-size:10px;border-radius:5px}.zone-tools button:hover{background:#fff9e7}.mini-map{position:absolute;right:32px;bottom:46px;width:186px;padding:8px;background:#f5f4e9e8;border:1px solid #c4ccbc;border-radius:7px;pointer-events:none}.mini-map svg{width:100%;display:block}.mini-map span{font-size:9px;color:#7a8977;display:block;text-align:center;margin-top:4px}.mini-map i{font-style:normal;margin:0 5px}.scene-controls{height:35px;padding:0 34px;display:flex;align-items:center;gap:22px;font-size:10px;color:#81907a}.source-caption{flex:1}.scene-controls select{border:0;background:transparent;color:#3a5a4c;font-size:10px;padding:5px}.scene-controls label{white-space:nowrap}.masthead{height:66px}.reference-gallery{inset:66px 0 0}.asset-dock{height:72px;margin-bottom:14px}.asset-list{justify-content:flex-start}.asset-list button{padding:8px 13px;gap:5px}.overview-tile{padding:8px}.scene-heading{max-width:460px}.scene-heading h1{font-size:30px}.scene-caption{bottom:18px}.scene-host canvas{outline:none}@media(max-width:900px){.mini-map{width:130px;right:16px}.zone-tools{right:16px;top:155px;max-width:330px}.scene-controls{padding:0 20px}.source-caption{max-width:55%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}}@media(max-width:600px){.mini-map{display:none}.zone-tools{left:20px;right:auto;top:151px;justify-content:flex-start}.scene-controls{gap:10px}.source-caption{max-width:42%}.scene-heading h1{font-size:23px}}
.replay-bar{display:flex;align-items:center;gap:15px;flex-shrink:0;height:64px;margin:0 32px;border-top:1px solid #b9c4b870}.play-button{width:38px;height:38px;flex-shrink:0;border:0;border-radius:50%;background:#355a4f;color:#faf7e9;font-size:12px}.reset-button{border:0;background:transparent;font-size:22px;color:#8b9a86}.timeline{flex:1;min-width:120px}.timeline-label{display:flex;justify-content:space-between;gap:15px;font-size:9px;color:#8b9983}.timeline-label strong{color:#3b5b4c;font-size:11px;font-weight:500;font-variant-numeric:tabular-nums}.timeline-label strong span{color:#9aa58e;font-size:9px}.timeline input{width:100%;accent-color:#597f65;height:12px;margin:8px 0 0;cursor:pointer}.timeline-label .blocked{color:#b67c21}.order-stage{color:#597c66}.replay-bar>select{border:0;background:transparent;font-size:11px;color:#52705c}.follow-order{border:1px solid #c4cdbb;background:#f3f3e7;border-radius:6px;font-size:10px;padding:10px 13px}.scene-controls input{accent-color:#617c63;vertical-align:middle}.selection-tag{top:auto;bottom:60px;left:32px;right:auto;max-width:270px}.mini-map{width:158px;bottom:48px}.scene-heading h1{font-size:26px}.scene-heading p{font-size:10px}@media(max-width:750px){.replay-bar{margin:0 18px;gap:8px}.follow-order{display:none}.timeline-label>span:last-child{display:none}.scene-controls label:has(input){display:none}.scene-controls{height:30px}.mini-map{display:none}}
.header-actions{display:flex;gap:26px}.sound-button{border:0;background:transparent;font-size:10px;white-space:nowrap;color:#637d67}.volume{width:55px;accent-color:#768b6f}.integration-message{position:absolute;left:32px;top:115px;max-width:440px;padding:12px 16px;background:#fff7e4;border:1px solid #d4c394;color:#96702d;font-size:11px;z-index:3}.integration-message button{display:block;border:0;border-bottom:1px solid #b8a16b;background:transparent;padding:7px 0 0;font-size:10px}@media(max-width:750px){.import-run,.volume{display:none}.header-actions{gap:8px}.sound-button{font-size:9px}.timeline-label .order-stage{display:none}}
.audio-options{position:relative;font-size:10px}.audio-options summary{cursor:pointer;list-style:none;padding:8px}.audio-options>div{position:absolute;right:0;bottom:30px;background:#f8f6ea;border:1px solid #c6cdbb;padding:12px;min-width:120px;z-index:4}.audio-options label{display:block;white-space:nowrap;padding:5px}.audio-options input{accent-color:#67856b;margin-right:8px}
